#!/usr/bin/env bash
# Installs yousj-meshd + yousj-mesh-hub on a Debian/Ubuntu host (co-located).
# Run as root on the server. Binaries are expected next to this script
# (yousj-meshd, yousj-mesh-hub, linux/amd64).
set -euo pipefail
cd "$(dirname "$0")"

install -m755 yousj-meshd /usr/local/bin/yousj-meshd
install -m755 yousj-mesh-hub /usr/local/bin/yousj-mesh-hub
mkdir -p /etc/yousj-mesh /var/lib/yousj-mesh

if [ ! -f /etc/yousj-mesh/hub.key ]; then
  # Hub X25519 keypair, generated by the hub binary itself (no external
  # tooling needed). The private key stays on this host, mode 600.
  /usr/local/bin/yousj-mesh-hub genkey > /tmp/hub-keypair.txt
  awk '/^private:/{print $2}' /tmp/hub-keypair.txt > /etc/yousj-mesh/hub.key
  awk '/^public:/{print $2}' /tmp/hub-keypair.txt > /etc/yousj-mesh/hub.pub
  chmod 600 /etc/yousj-mesh/hub.key
  rm -f /tmp/hub-keypair.txt
  echo "hub public key: $(cat /etc/yousj-mesh/hub.pub)"
fi

echo "Next steps:"
echo "  1. Create /etc/yousj-mesh/meshd.json (see README.md), with hub_pubkey = contents of /etc/yousj-mesh/hub.pub"
echo "  2. Create /etc/yousj-mesh/hub.env with MESHD_URL, MESHHUB_TOKEN, HUB_PORT"
echo "  3. systemctl enable --now yousj-meshd yousj-mesh-hub"
echo "  4. sysctl -w net.ipv4.ip_forward=1 (and persist it) so the hub can forward member traffic"
